        for c in range(w):
            v = grid[r][c]
            if v != 8 and v != 0 and (r, c) not in visited:
                # BFS to find region
                region = []
                queue = [(r, c)]
                while queue:
                    cr, cc = queue.pop(0)
                    if (cr, cc) not in visited and 0 <= cr < h and 0 <= cc < w:
                        if grid[cr][cc] not in (8, 0):
                            visited.add((cr, cc))
                            region.append((cr, cc, grid[cr][cc]))
                            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
